Write a client application using gradle in different terminal.

* Install Gradle

  ```bash
  export SOURCE_ROOT=/<source_root>/
  export GRADLE_VERSION="9.4.1" # only for rhel-10.x
  export GRADLE_VERSION="7.3.3" # except for rhel-10.x
  cd $SOURCE_ROOT
  wget https://services.gradle.org/distributions/gradle-$GRADLE_VERSION-bin.zip
  unzip -q gradle-$GRADLE_VERSION-bin.zip
  export JAVA_HOME=<path to java>
  export PATH=$JAVA_HOME/bin:$PATH:$SOURCE_ROOT/gradle-$GRADLE_VERSION/bin
  ```

* Create `$SOURCE_ROOT/build.gradle` file with following contents

  ```gradle
  apply plugin: 'java'
  apply plugin: 'application'
  application {
    mainClass = 'HelloWorld'
  }
  repositories { 
      mavenCentral()  
  }
  dependencies {
      implementation 'org.apache.geode:geode-core:2.0.3'    
      implementation 'org.apache.logging.log4j:log4j-api:2.25.3'
      implementation 'org.apache.logging.log4j:log4j-slf4j-impl:2.25.3'
      implementation 'org.apache.logging.log4j:log4j-core:2.25.3'
  }
  ```

* Create directory `$SOURCE_ROOT/src/main/java` and create a file at `$SOURCE_ROOT/src/main/java/HelloWorld.java` with following contents 

  ```java
  import java.util.Map;
  import org.apache.geode.cache.Region;
  import org.apache.geode.cache.client.*;

  public class HelloWorld {
    public static void main(String[] args) throws Exception {
      ClientCache cache = new ClientCacheFactory()
        .addPoolLocator("localhost", 10334)
        .create();
      Region<String, String> region = cache
        .<String, String>createClientRegionFactory(ClientRegionShortcut.CACHING_PROXY)
        .create("hello");

      region.put("1", "Hello");
      region.put("2", "World");

      for (Map.Entry<String, String>  entry : region.entrySet()) {
        System.out.format("key = %s, value = %s\n", entry.getKey(), entry.getValue());
      }
      cache.close();
    }
  }
  ```

* Build and run the HelloWorld example:

  ```bash
  gradle run
  ```

